<?php
$f = 'operator/live_sessions.php';
$c = file_get_contents($f);

$start = strpos($c, '<?php foreach($sessions as $sess):');
$end = strpos($c, '<?php endforeach; ?>') + 20;

if ($start !== false && $end !== false) {
    $replacement = base64_decode(' ');
    
    $c = substr_replace($c, $replacement, $start, $end - $start);
    file_put_contents($f, $c);
    echo "Fixed using base64.\n";
} else {
    echo "Bounds not found.\n";
}
?>
